
const {assert}=require('./core.cjs');
const CONFIG={apiKey:'AIzaSyB2WZbeHZSUg2esHZfBQ0KS2HWea5wXq8Y',databaseURL:'https://boralancesstudios-default-rtdb.firebaseio.com',projectId:'boralancesstudios'};
const ROOT='boralanceslauncher/main';
const ERRORS={CONFIGURATION_NOT_FOUND:'Enable Firebase Authentication and Email/Password in the project console.',OPERATION_NOT_ALLOWED:'Enable Email/Password sign-in in Firebase Authentication.',INVALID_LOGIN_CREDENTIALS:'Incorrect email or password.',EMAIL_EXISTS:'This email already has an account.',TOO_MANY_ATTEMPTS_TRY_LATER:'Too many attempts. Try again later.'};
function segment(s){assert(typeof s==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(s),'Invalid cloud record ID.');return s;}
function email(value){const s=String(value||'').trim();return s.toLowerCase()==='admin'?'admin@boralanceslauncher.app':s;}
class Firebase{
 constructor(session=null,fetcher=fetch,ownerUID=null){this.session=session;this.fetch=fetcher;this.ownerUID=ownerUID;}
 async request(url,options={}){let r;try{r=await this.fetch(url,{...options,signal:AbortSignal.timeout(20000)});}catch{throw new Error('Firebase is unreachable. Your local launcher remains available.');}const j=await r.json().catch(()=>null);if(!r.ok){const e=j?.error?.message||j?.error;throw new Error(ERRORS[e]||(r.status===401||r.status===403?'Firebase permission denied. Merge only the boralanceslauncher fragment into your existing database rules.':'Firebase request failed ('+r.status+').'));}return j;}
 async authenticate(p){const address=email(p.email);assert(/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(address),'Enter an email address, or Admin.');assert(typeof p.password==='string'&&p.password.length>=8&&p.password.length<=128,'Use a password with 8–128 characters.');if(p.signup)assert(/^[A-Za-z0-9_]{3,24}$/.test(p.name||''),'Display names use 3–24 letters, numbers or underscores.');
  const j=await this.request('https://identitytoolkit.googleapis.com/v1/accounts:'+(p.signup?'signUp':'signInWithPassword')+'?key='+CONFIG.apiKey,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:address,password:p.password,returnSecureToken:true})});
  this.session={uid:j.localId,email:j.email,idToken:j.idToken,refreshToken:j.refreshToken,expires:Date.now()+Number(j.expiresIn)*1000,name:p.signup?p.name:(j.displayName||address.split('@')[0])};
  if(p.signup)await this.request('https://identitytoolkit.googleapis.com/v1/accounts:update?key='+CONFIG.apiKey,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({idToken:j.idToken,displayName:p.name,returnSecureToken:false})});
  return this.public();
 }
 async token(){assert(this.session,'Sign in to your launcher account.');if(this.session.expires<Date.now()+60000){const j=await this.request('https://securetoken.googleapis.com/v1/token?key='+CONFIG.apiKey,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({grant_type:'refresh_token',refresh_token:this.session.refreshToken}).toString()});Object.assign(this.session,{idToken:j.id_token,refreshToken:j.refresh_token,expires:Date.now()+Number(j.expires_in)*1000});}return this.session.idToken;}
 public(){if(!this.session)return null;return {uid:this.session.uid,email:this.session.email,name:this.session.name,admin:!!this.ownerUID&&this.session.uid===this.ownerUID,ownerPC:!!this.ownerUID};}
 async db(relative,method='GET',value){assert(relative.split('/').every(s=>/^[A-Za-z0-9_-]+$/.test(s)),'Invalid cloud path.');const token=this.session?await this.token():null;return this.request(CONFIG.databaseURL+'/'+ROOT+'/'+relative+'.json'+(token?'?auth='+encodeURIComponent(token):''),{method,headers:{'Content-Type':'application/json'},...(value!==undefined?{body:JSON.stringify(value)}:{})});}
 async sync(profile){assert(this.session,'Sign in to sync.');return this.db('name/'+segment(this.session.uid),'PATCH',profile);}
 async data(){assert(this.session,'Sign in to sync.');return this.db('name/'+segment(this.session.uid));}
 async publish(kind,p){assert(this.public()?.admin,'Admin access requires your enrolled Windows owner account and its matching Firebase login.');assert(['servers','featured','cosmetics'].includes(kind),'Unknown featured collection.');segment(p.id);const item=validatePublication(kind,p);await this.db('public/'+kind+'/'+p.id,'PUT',item);return item;}
 async redeem(code){assert(this.session,'Sign in to redeem a voucher.');const normalized=String(code||'').trim().toUpperCase().replace(/-/g,'');assert(/^[A-Z0-9]{16,64}$/.test(normalized),'Enter a valid voucher code.');const digest=require('node:crypto').createHash('sha256').update(normalized).digest('hex');if(!await this.db('redemptions/'+segment(this.session.uid)+'/'+digest))await this.db('redemptions/'+segment(this.session.uid)+'/'+digest,'PUT',{redeemedAt:Date.now()});const voucher=await this.db('vouchers/'+digest);assert(voucher?.product,'Voucher is invalid or expired.');await this.db('entitlements/'+segment(this.session.uid)+'/'+segment(voucher.product),'PUT',{voucher:digest});return voucher.product;}
}
function validatePublication(kind,p){
 const name=String(p.name||'').trim();assert(name.length>0&&name.length<=80,'Enter a title up to 80 characters.');const base={id:segment(p.id),name,description:String(p.description||'').slice(0,500)};
 if(kind==='servers'){assert(/^[A-Za-z0-9.-]+(?::[0-9]{1,5})?$/.test(p.address||''),'Use a hostname with an optional port.');const port=Number(p.address.split(':')[1]||25565);assert(port>=1&&port<=65535,'Invalid port.');return {...base,address:p.address,version:String(p.version||'').slice(0,40)};}
 if(kind==='featured'){assert(['curseforge','modrinth'].includes(p.provider),'Choose a provider.');assert(['mod','modpack','shader','resourcepack','datapack'].includes(p.type),'Choose a project type.');assert(/^[A-Za-z0-9_-]{1,100}$/.test(p.projectId||''),'Invalid project ID.');return {...base,provider:p.provider,type:p.type,projectId:p.projectId};}
 assert(['Cape','Wings','Animated Wings','Skin','Hat','Trinket','Dress'].includes(p.type),'Choose a cosmetic type.');assert(typeof p.texture==='string'&&p.texture.length<1500000,'Texture too large.');const bytes=Buffer.from(p.texture,'base64');if(require('./wearables.cjs').TYPES[p.type])require('./wearables.cjs').validateOverlay(bytes,p.type);else require('./player-style.cjs').validatePNG(bytes,p.type==='Skin'?'skin':p.type==='Animated Wings'?'wing':'cape');return {...base,type:p.type,texture:p.texture,price:0,voucherOnly:p.type==='Skin'||!!p.voucherOnly};
}
module.exports={Firebase,CONFIG,ROOT,segment,validatePublication};
